def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    pressure_bids = []
    desperate_count = 0
    rich_count = 0

    for opp in alive_opponents:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('budget', 0) >= budget:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                bid = float(bid)
                prev_bids.append(bid)
                if prev.get('status') == 'success' or prev.get('hp_after', opp.get('hp', 10)) <= 3:
                    pressure_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    high_pressure = max(pressure_bids) if pressure_bids else highest_prev

    scarcity = (supply <= 17)
    abundant = (supply >= 22)
    critical_me = (hp <= 2 or no_water_days >= 2)
    urgent_me = (hp <= 4 or no_water_days >= 1)

    if critical_me:
        target = max(DAILY_SALARY * 0.95, high_pressure + 2.0)
        if scarcity:
            target = max(target, DAILY_SALARY * 1.15)
        return float(min(budget, target))

    if abundant:
        if highest_prev >= DAILY_SALARY * 1.3 and hp >= 5:
            return float(min(budget, DAILY_SALARY * 0.18))
        if highest_prev <= DAILY_SALARY * 0.55:
            return float(min(budget, max(DAILY_SALARY * 0.32, avg_prev + 1.0)))
        return float(min(budget, DAILY_SALARY * 0.28))

    if scarcity:
        if high_pressure >= DAILY_SALARY * 1.4 and hp >= 6:
            return float(min(budget, DAILY_SALARY * 0.22))
        if urgent_me:
            target = max(DAILY_SALARY * 0.88, high_pressure + 1.5)
            return float(min(budget, target))
        if desperate_count >= 2:
            return float(min(budget, DAILY_SALARY * 0.2))
        target = max(DAILY_SALARY * 0.58, min(high_pressure + 1.0, DAILY_SALARY * 0.82))
        return float(min(budget, target))

    if urgent_me:
        target = max(DAILY_SALARY * 0.72, min(high_pressure + 1.0, DAILY_SALARY * 0.95))
        return float(min(budget, target))

    if highest_prev >= DAILY_SALARY * 1.25 and hp >= 5:
        return float(min(budget, DAILY_SALARY * 0.24))

    if rich_count >= 2 and hp >= 6:
        return float(min(budget, DAILY_SALARY * 0.3))

    target = max(DAILY_SALARY * 0.42, min(avg_prev + 1.0, DAILY_SALARY * 0.68))
    if day >= 8 and hp >= 6:
        target = min(target, DAILY_SALARY * 0.38)
    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp and opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    prev_pressures = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass
        # If they were already in trouble yesterday, assume higher urgency today
        prev_hp_after = prev.get('hp_after', None)
        if prev_hp_after is not None:
            try:
                prev_pressures.append(float(prev_hp_after))
            except Exception:
                pass

    # Baseline bid target from yesterday's market
    if prev_bids:
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        max_prev = max(prev_bids)
        # If market was aggressive, we try to slightly overtake mid/high bids.
        # Use a conservative overbid factor to conserve budget.
        target = avg_prev * 0.98
        # If supply is high, winning is easier; we can bid lower than max.
        # If supply is low, we increase target to avoid losing.
        if supply <= float(MIN_SUPPLY) + 1.0:
            target = max(target, avg_prev * 1.05)
        elif supply >= float(MAX_SUPPLY) - 1.0:
            target = min(target, avg_prev * 0.95)

        # If someone bid extremely high yesterday, avoid getting undercut.
        if max_prev >= DAILY_SALARY * 1.15:
            target = max(target, max_prev * 0.92)
    else:
        target = DAILY_SALARY * 0.55

    # Urgency adjustments based on my hp and no_water_days
    # If I'm close to death, bid more to secure water.
    if hp <= 2.0 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.85)
    elif hp <= 4.0:
        target = max(target, DAILY_SALARY * 0.65)

    # If supply is scarce, scale up; if abundant, scale down.
    # Convert supply to a scarcity factor in [0,1]
    denom = float(MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        scarcity = 0.5
    else:
        scarcity = (float(MAX_SUPPLY) - supply) / denom
        if scarcity < 0.0:
            scarcity = 0.0
        if scarcity > 1.0:
            scarcity = 1.0

    target = target * (0.85 + 0.3 * scarcity)

    # Cap target to a fraction of budget to avoid bankruptcy
    # If budget is low, we must spend to survive.
    if budget <= DAILY_SALARY * 0.7:
        cap_frac = 0.95
    else:
        cap_frac = 0.7

    bid = min(budget, target * cap_frac)

    # Ensure bid is non-negative and not trivially tiny
    if bid < 0.0:
        bid = 0.0

    # If we have enough budget, keep a minimum competitive bid.
    min_competitive = DAILY_SALARY * 0.35
    if budget >= min_competitive and bid < min_competitive:
        bid = min_competitive

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Estimate if yesterday's highest bid was aggressive
    aggressive_yesterday = False
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        if max_prev_bid >= DAILY_SALARY * 0.85:
            aggressive_yesterday = True

    # Base bid: moderate
    base_bid = DAILY_SALARY * 0.5

    # Adjust for HP
    if hp <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif hp <= 4:
        base_bid = DAILY_SALARY * 0.75

    # Adjust for supply scarcity
    supply_ratio = supply / MAX_SUPPLY
    if supply_ratio < 0.7:
        base_bid *= 1.2
    elif supply_ratio > 0.9:
        base_bid *= 0.85

    # Respond to yesterday's aggression: if they bid high, they may be low on budget; we can undercut
    if aggressive_yesterday:
        # They spent a lot, so might be weak today; we can bid lower if we don't need water
        if hp > 4:
            base_bid = min(base_bid, DAILY_SALARY * 0.35)
    else:
        # They saved budget, may outbid us; increase bid if we need water
        if hp <= 3:
            base_bid = max(base_bid, DAILY_SALARY * 0.8)

    final_bid = min(budget, base_bid)
    # Ensure we don't bid more than we have
    final_bid = min(budget, max(0, final_bid))
    return int(final_bid)
